def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid separator row or column.
    sep = None
    for r, row in enumerate(grid):
        if row[0] != 0 and all(x == row[0] for x in row):
            sep = ("row", r)
            break
    if sep is None:
        for c in range(w):
            if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
                sep = ("col", c)
                break

    if sep[0] == "row":
        _, r = sep
        parts = [grid[:r], grid[r + 1:]]
    else:
        _, c = sep
        parts = [
            [row[:c] for row in grid],
            [row[c + 1:] for row in grid],
        ]

    def density(part):
        cells = [x for row in part for x in row]
        return sum(x != 0 for x in cells) / len(cells)

    chosen = min(parts, key=density)
    return [[2 if x != 0 else 0 for x in row] for row in chosen]
